package com.example.lending.adapter.out.persistence;

import com.example.lending.domain.AuditAction;
import com.example.lending.domain.AuditLog;
import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

import java.time.Instant;
import java.util.UUID;

@Entity
@Table(name = "audit_log")
public class AuditLogJpaEntity {

    // 자동 증가 번호다. 발생 시각이 같은 기록은 이 번호로 순서를 정한다
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long seq;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false)
    private AuditAction action;

    @Column(nullable = false)
    private UUID targetId;

    private UUID memberId;

    @Column(nullable = false)
    private Instant occurredAt;

    protected AuditLogJpaEntity() {
    }

    private AuditLogJpaEntity(AuditAction action, UUID targetId, UUID memberId, Instant occurredAt) {
        this.action = action;
        this.targetId = targetId;
        this.memberId = memberId;
        this.occurredAt = occurredAt;
    }

    static AuditLogJpaEntity from(AuditLog auditLog) {
        return new AuditLogJpaEntity(auditLog.action(), auditLog.targetId(), auditLog.memberId(),
                auditLog.occurredAt());
    }

    AuditLog toDomain() {
        return new AuditLog(action, targetId, memberId, occurredAt);
    }
}

