import com.example.lending.domain.Member;
import com.example.lending.domain.MemberNotFoundException;
import com.example.lending.domain.Reservation;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDate;
import java.util.List;
import java.util.Optional;

@Service
@Transactional
public class LoanBookService implements LoanBookUseCase {

    private final LoadBookPort loadBookPort;
    private final SaveBookPort saveBookPort;
    private final LoadMemberPort loadMemberPort;
    private final LoadLoanPort loadLoanPort;
    private final SaveLoanPort saveLoanPort;
    private final LoadReservationPort loadReservationPort;
    private final DeleteReservationPort deleteReservationPort;
    private final CreditCheckPort creditCheckPort;
    private final SaveAuditLogPort saveAuditLogPort;

    public LoanBookService(LoadBookPort loadBookPort, SaveBookPort saveBookPort, LoadMemberPort loadMemberPort,
                           LoadLoanPort loadLoanPort, SaveLoanPort saveLoanPort,
                           LoadReservationPort loadReservationPort, DeleteReservationPort deleteReservationPort,
                           CreditCheckPort creditCheckPort, SaveAuditLogPort saveAuditLogPort) {
        this.loadBookPort = loadBookPort;
        this.saveBookPort = saveBookPort;
        this.loadMemberPort = loadMemberPort;
        this.loadLoanPort = loadLoanPort;
        this.saveLoanPort = saveLoanPort;
        this.loadReservationPort = loadReservationPort;
        this.deleteReservationPort = deleteReservationPort;
        this.creditCheckPort = creditCheckPort;
    }

    @Override
    public Loan loanBook(LoanBookCommand command) {
        Member member = loadMemberPort.loadMemberForUpdate(command.memberId())
                .orElseThrow(() -> new MemberNotFoundException(command.memberId()));
        member.ensureCanBorrow(loadLoanPort.countActiveLoansByMemberId(member.getId()));

        // 거절되면 예외로 트랜잭션이 롤백되어 도서 상태는 그대로 남는다. 도서 행 잠금 전에 조회해서 외부 호출 동안 도서를 잠그지 않는다
        CreditCheck creditCheck = creditCheckPort.check(member.getId(), member.getName());
        if (!creditCheck.approved()) {
            throw new CreditRejectedException(member.getId());
        }

        Book book = loadBookPort.loadBookForUpdate(command.bookId())
                .orElseThrow(() -> new BookNotFoundException(command.bookId()));
        List<Reservation> reservations = loadReservationPort.loadReservationsForBook(book.getId());
        Optional<Reservation> nextReservation = reservations.stream().findFirst();
        LocalDate loanedAt = command.loanedAt() != null ? command.loanedAt() : LocalDate.now();
        Loan loan = book.loanTo(command.memberId(), loanedAt, nextReservation.map(Reservation::getMemberId),
                creditCheck);
        nextReservation.ifPresent(reservation -> deleteReservationPort.deleteReservation(reservation.getId()));
        saveBookPort.saveBook(book);
        saveLoanPort.saveLoan(loan);
        return loan;
    }
}

